/**
 * Build `src/analysis/wasm/gram.generated.ts` from `src/analysis/wasm/gram.c`.
 *
 * The correlation kernel is C compiled to WebAssembly twice — with SIMD, and
 * with relaxed SIMD — and both modules are committed as base64 in a TypeScript
 * file, so the app builds with no C toolchain and loads no file at run time: only
 * whoever changes the C needs clang (with the `wasm32` target) and lld. Re-run
 * with `npm run wasm` after changing it; `test/unit/pearson-rows.test.ts` fails
 * until you do, since the generated file records the hash of the source it was
 * built from.
 *
 *   npm run wasm
 */

import { execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const source = join(root, 'src/analysis/wasm/gram.c')
const target = join(root, 'src/analysis/wasm/gram.generated.ts')

// clang looks for the linker as `wasm-ld`, which is lld under another name and
// is not always installed as one: a symlink on a private PATH entry answers it.
const work = mkdtempSync(join(tmpdir(), 'gram-wasm-'))
try {
  const lld = execFileSync('which', ['lld'], { encoding: 'utf8' }).trim()
  symlinkSync(lld, join(work, 'wasm-ld'))
} catch {
  // A `wasm-ld` already on PATH is used as it is.
}
const build = (name, flags) => {
  const out = join(work, name)
  execFileSync(
    'clang',
    [
      '--target=wasm32',
      '-O3',
      '-msimd128',
      ...flags,
      '-nostdlib',
      '-Wl,--no-entry',
      '-Wl,--import-memory',
      '-Wl,--export-dynamic',
      '-o',
      out,
      source,
    ],
    { stdio: 'inherit', env: { ...process.env, PATH: `${work}:${process.env.PATH ?? ''}` } },
  )
  return readFileSync(out)
}
const literal = (bytes) =>
  (bytes.toString('base64').match(/.{1,100}/g) ?? [])
    .map((line, i, all) => `  '${line}'${i === all.length - 1 ? '' : ' +'}`)
    .join('\n')
try {
  // The same source twice: SIMD alone, and with the relaxed multiply-add an
  // engine may fuse (`gram.c` says why).
  const plain = build('gram.wasm', [])
  const relaxed = build('gram-relaxed.wasm', ['-mrelaxed-simd'])
  const hash = createHash('sha256').update(readFileSync(source)).digest('hex')
  writeFileSync(
    target,
    `/**
 * Generated by \`npm run wasm\` from \`gram.c\` — do not edit.
 *
 * The correlation kernel (§18.6) as WebAssembly modules, base64, so the app
 * carries them with no loader and no C toolchain: with SIMD
 * (${plain.length.toLocaleString('en')} bytes), and with relaxed SIMD, whose
 * multiply-add may be fused (${relaxed.length.toLocaleString('en')} bytes).
 */

/** The SHA-256 of the \`gram.c\` these were built from, which a test compares. */
export const GRAM_SOURCE_SHA256 = '${hash}'

export const GRAM_WASM_BASE64 =
${literal(plain)}

export const GRAM_RELAXED_WASM_BASE64 =
${literal(relaxed)}
`,
  )
  console.log(`wrote ${target} (${plain.length} and ${relaxed.length} bytes of wasm, source ${hash.slice(0, 12)})`)
} finally {
  rmSync(work, { recursive: true, force: true })
}
